#!/usr/bin/env python3
"""Write reports/paper_ready_summary.md from the configuration and the result files. Nothing is typed in by hand:
parameters come from config/params.yaml and the code constants, numbers from

    benchmarks/results/ablation_summary.json      (run_ablation_suite.py)
    benchmarks/results/fixture_results.json       (summarise_fixtures.py)
    reports/baseline_data/v2s3_onfly_metrics.json, v2s3_soil_runs.json
    videos/morph_conference_video_60fps.json      (record_conference_video.py)

    cd simulation && source install/setup.bash && python3 benchmarks/generate_paper_summary.py

A missing input produces a "not measured yet" line, never a placeholder number.
"""
import json, math
from pathlib import Path
import yaml
from morph_sim import decision_core as dc, control, trench_crossing as tc

WS = Path(__file__).resolve().parents[1]
PKG = WS / 'src/morph_sim'
LABEL = {'fixed_compact': 'Fixed Compact', 'fixed_extended': 'Fixed Extended', 'reactive': 'Reactive (stop, then morph)', 'proposed': 'Proposed (predictive swerve-morph)'}
BRIEF_NAME = {'fixed_compact': 'fixed_compact', 'fixed_extended': 'fixed_extended', 'reactive': 'reactive_stop_morph', 'proposed': 'proposed_predictive_swerve_morph'}


def load(path):
    path = WS / path
    return json.loads(path.read_text()) if path.exists() else None


def pm(entry, digits=1, scale=1.):
    if not entry: return 'n/a'
    return f"{scale * entry['mean']:.{digits}f} ± {scale * entry['std']:.{digits}f}"


def main():
    p = yaml.safe_load((PKG / 'config/params.yaml').read_text()); arena = json.loads((PKG / 'config/tetra_arena.json').read_text())
    ablation = load('benchmarks/results/ablation_summary.json'); fixtures = load('benchmarks/results/fixture_results.json')
    onfly = load('reports/baseline_data/v2s3_onfly_metrics.json'); soil = load('reports/baseline_data/v2s3_soil_runs.json'); video = load('videos/morph_conference_video_60fps.json')
    robot, drive, steer, motion = p['robot'], p['drive'], p['steering'], p['motion']; mass = robot['mass_kg']; out = []; w = out.append
    force = 4 * drive['output_torque_limit_Nm'] / robot['wheel_radius_m']; boost = force * (1 + drive['peak_boost_fraction'])

    w('# MORPH rover — paper-ready summary (generated)\n')
    w('Generated by `benchmarks/generate_paper_summary.py`; do not edit by hand. **Everything here is simulation of an')
    w('assumed-parameter model. No hardware exists yet and no parameter has been measured on hardware.** Pose and speed')
    w('in the benchmarks come from simulator ground truth. Paper naming: *Reconfigurable Longitudinal Wheelbase and')
    w('Stance Adaptation*; the track is fixed.\n')

    w('## 1. Model\n')
    w('| Quantity | Value | Source |\n|---|---|---|')
    for name, value, source in [
            ('Mass', f"{mass:g} kg", 'params.yaml, assumed'), ('Wheel radius × width', f"{1e3 * robot['wheel_radius_m']:.0f} × {1e3 * robot['wheel_width_m']:.0f} mm", 'params.yaml, assumed'),
            ('Track (fixed)', f"{1e3 * dc.TRACK:.0f} mm", 'URDF'), ('Wheelbase Compact / Normal / Extended', ' / '.join(f"{1e3 * dc.wheelbase(s):.0f}" for s in ('COMPACT', 'NORMAL', 'EXTENDED')) + ' mm', 'URDF joint limits, L = 0.54 + 8d'),
            ('Centre-of-mass height', f"{1e3 * dc.COM_HEIGHT:.0f} mm", 'URDF inertials (Phase 0 audit)'), ('Static tip-over angle, pitch axis', ' / '.join(f"{dc.stability_margin(dc.wheelbase(s)) if dc.wheelbase(s) < dc.TRACK else math.degrees(math.atan(dc.wheelbase(s) / 2 / dc.COM_HEIGHT)):.1f}" for s in ('COMPACT', 'NORMAL', 'EXTENDED')) + ' deg', 'atan(L / 2h)'),
            ('Static tip-over angle, roll axis', f"{math.degrees(math.atan(dc.TRACK / 2 / dc.COM_HEIGHT)):.1f} deg (all stances)", 'atan(T / 2h)'),
            ('Drive torque limit per wheel', f"{drive['output_torque_limit_Nm']:g} Nm → {force:.1f} N total", 'params.yaml, assumed'),
            ('Peak boost', f"+{100 * drive['peak_boost_fraction']:.0f} % → {boost:.1f} N, fading from {drive['peak_boost_derate_C']:g} °C to {drive['derate_C']:g} °C winding temperature", 'params.yaml'),
            ('Steering rate limit', f"{steer['output_speed_limit_rad_s']:g} rad/s ({math.degrees(steer['output_speed_limit_rad_s']):.0f} deg/s); steering range ±90 deg", 'params.yaml (brief value)'),
            ('Rail speed per stage', f"{1e3 * control.MORPH_STAGE_RATE:.1f} mm/s commanded, {1e3 * dc.STAGE_RATE:.1f} mm/s measured", 'Phase 0 baseline'),
            ('Full shape change 237 ↔ 672 mm', f"{dc.T_FULL:.1f} s (calculated from the measured rail rate)", 'decision_core.T_FULL'),
            ('Corner height actuators', f"±{1e3 * control.HEIGHT_LIMIT:.0f} mm", 'URDF'), ('Jerk limit', f"{motion['jerk_limit_m_s3']:g} m/s³ linear, {motion['yaw_jerk_limit_rad_s3']:g} rad/s³ yaw", 'params.yaml (brief value)'),
            ('Acceleration limit', f"{motion['friction_acceleration_fraction']:g} · μ · g, clamped to {motion['acceleration_floor_m_s2']:g}–{motion['acceleration_ceiling_m_s2']:g} m/s²", 'params.yaml'),
            ('Trimmed body length (Compact)', f"{1e3 * dc.CRAB_LENGTH['COMPACT']:.0f} mm; width over tyres {1e3 * dc.TYRE_WIDTH:.0f} mm, over drive units {1e3 * dc.BODY_WIDTH:.0f} mm", 'URDF collision envelope')]:
        w(f'| {name} | {value} | {source} |')

    w('\n## 2. Equations (as implemented)\n')
    w('Body twist $(v_x, v_y, \\omega_z)$, stage offset $d$, wheelbase $L = 0.54 + 8d$, wheel $i$ at $r_i(L) = (\\pm L/2, \\pm T/2)$.\n')
    w('**Coupled swerve and wheelbase kinematics** (`control.wheel_velocity`):\n')
    w('$$v_i = \\begin{bmatrix} v_x - \\omega_z r_{i,y} \\\\ v_y + \\omega_z r_{i,x} \\end{bmatrix} + \\frac{\\partial r_i}{\\partial L}\\dot L, \\qquad \\frac{\\partial r_i}{\\partial L}\\dot L = (\\pm 4\\dot d,\\ 0)$$\n')
    w('$$\\delta_i = \\operatorname{atan2}(v_{i,y}, v_{i,x}), \\qquad \\omega_i = \\lVert v_i \\rVert / R$$\n')
    w('$\\dot L$ is the measured rail rate (50 ms low-pass). Angles are folded into ±90° with a signed wheel speed.\n')
    w('**Alignment scaling** (`control.AdaptationCore.step`): $v_{exec,i} = v_{cmd,i} \\cos^2(\\theta_{err,i})$.\n')
    w('**Jerk-limited command** (`control.jerk_limited_step`), per axis, with $J$ the jerk limit and $e$ the remaining speed error:\n')
    w('$$a^* = \\sqrt{(J\\,\\Delta t/2)^2 + 2 J |e|} - J\\,\\Delta t / 2, \\qquad |\\dot a| \\le J, \\qquad |a| \\le a_{max}(\\mu) = \\operatorname{clip}(0.35\\,\\mu g,\\ 0.4,\\ 2.2)$$\n')
    w('**Static stability margin** (`decision_core.stability_margins`), gravity in the body frame $g_b$, CoM height $h$:\n')
    w('$$m_{front/rear} = \\arctan\\frac{L/2 \\mp x_c}{h} \\mp \\operatorname{atan2}(g_{b,x}, -g_{b,z}), \\qquad m_{left/right} = \\arctan\\frac{T/2 \\mp y_c}{h} \\mp \\operatorname{atan2}(g_{b,y}, -g_{b,z}), \\qquad m = \\min(\\cdot)$$\n')
    w('**Axle loads on a slope** $\\theta$ (`decision_core.axle_loads`): $N_{r,f} = \\tfrac12 mg\\cos\\theta \\pm mg\\sin\\theta\\, h / L$.\n')
    w('**Traction utilisation** (`decision_core.traction_utilisation`): $u = \\dfrac{mg\\sin\\theta + R_{soil} + R_{roll}}{\\sum_{axles} \\min(\\mu N_a,\\ 2\\tau_{max}/R)}$; a stance with $u > 1$ is infeasible.\n')
    w('**Winding temperature rise** (`decision_core.winding_rise`): $\\Delta T = I^2 R_w R_{th}$, $I = \\dfrac{F R / 4}{k_t\\, G\\, \\eta}$.\n')
    w('**Stance cost** (`decision_core.evaluate`), minimised over $S \\in \\{$Compact, Normal, Extended$\\}$:\n')
    w('$$J(S) = \\frac{20^\\circ}{m(S)} + \\frac{\\Delta T(S)}{T_{derate} - T} + u(S) + J_{clear}(S) + 0.2\\,\\frac{t_{morph}(S)}{T_{full}}$$\n')
    w('$J_{clear}$ is 20 mm divided by the spare margin (capped at 5) and infinite when the stance does not fit the passage or cannot step the trench.\n')
    w('**Predictive trigger** (`decision_core.lookahead_trigger`): start the shape change when $d / v \\le t_{morph} + 1.0\\ \\text{s}$, with $t_{morph} = |d_{target} - d| / \\dot d_{rail}$.\n')
    w('**Trench stepping** (`trench_crossing`): along-travel wheel offsets $\\pm\\tfrac L2\\cos\\psi \\pm \\tfrac T2\\sin\\psi$; a trench of width $w$ can be stepped one wheel at a time when the smallest spacing exceeds $w + 60$ mm.')
    w('Best spacing: ' + ', '.join(f"{s.title()} {1e3 * tc.best_yaw(dc.SHAPES[s])[1]:.0f} mm at {math.degrees(tc.best_yaw(dc.SHAPES[s])[0]):.0f}° yaw" for s in ('COMPACT', 'NORMAL', 'EXTENDED')) + '.\n')
    w('**Soil resistance** (`terramechanics.py`, `src/terramechanics_model.hpp`), rigid wheel of width $b$, diameter $D$, load $W$, Bekker constants $k_c, k_\\phi, n$:\n')
    w('$$z = \\left[\\frac{3W}{(3-n)(k_c + b k_\\phi)\\sqrt D}\\right]^{\\frac{2}{2n+1}}, \\qquad R_c = b\\left(\\frac{k_c}{b} + k_\\phi\\right)\\frac{z^{n+1}}{n+1}$$\n')
    w('A wheel that follows in an existing rut pays only the work of deepening it (plus a reload fraction). The soil slip is estimated from Janosi–Hanamoto, $H = (Ac + W\\tan\\phi)\\left[1 - \\tfrac{K}{s l}(1 - e^{-s l / K})\\right]$. The resistance is applied as a wheel torque over rigid contact; the ground does not deform.\n')

    w('## 3. Arena (`worlds/tetra_arena.sdf`, seed ' + str(arena.get('seed')) + ')\n')
    w('| Zone | x range [m] | Surface | Feature |\n|---|---|---|---|')
    for z in arena['zones']:
        feature = ''
        if z.get('trenches'): feature = 'transverse trenches ' + ' / '.join(f"{1e3 * t['width_m']:.0f}" for t in z['trenches']) + f" mm wide, {1e3 * z['trenches'][0]['depth_m']:.0f} mm deep"
        elif z.get('ramps'): feature = 'tour ramp ' + ', '.join(f"{r['angle_deg']:g}°" for r in z['ramps'][:1]) + '; test ramps ' + ', '.join(f"{r['angle_deg']:g}°" for r in z['ramps'][1:]) + f" (rise {z['ramps'][0]['rise_m']:g} m)"
        elif z.get('clear_width_m'): feature = f"{1e3 * z['clear_width_m']:.0f} mm clear width, walls {1e3 * z['wall_height_m']:.0f} mm high"
        elif z.get('soil'): feature = f"μ = {z.get('mu')}, soil model `{z['soil']}`"
        elif z.get('obstacle_height_m'): feature = f"{len(z.get('obstacles', []))} fixed obstacles, {1e3 * z['obstacle_height_m']:.0f} mm high"
        w(f"| {z['id']} | {z['bounds'][0]:g} – {z['bounds'][1]:g} | {z.get('surface', '')} | {feature} |")

    w('\n## 4. Ablation over the autonomous tour\n')
    if ablation and ablation.get('policies'):
        pol = ablation['policies']; names = [n for n in LABEL if n in pol]
        w(f"{len(ablation['runs'])} runs, {ablation['scope']}. Mean ± sample standard deviation over n runs. A zone a policy cannot pass is recorded as failed and the robot is")
        w('placed past it, so time, distance and energy of a failing policy cover only the zones it drove.\n')
        w('| Policy | n | Tour complete | Zones passed (of 10) | Time [s] | Energy [J] | Cost of transport | Lowest tip margin [deg] | Peak winding [°C] | RMS wheel slip [%] |\n|---|---|---|---|---|---|---|---|---|---|')
        for n in names:
            e = pol[n]; w(f"| {LABEL[n]} (`{BRIEF_NAME[n]}`) | {e['runs']} | {e['task_success']['mean'] * e['runs']:.0f} of {e['runs']} | {pm(e['zones_passed'])} | {pm(e['mission_time_s'])} | {pm(e['energy_J'], 0)} | {pm(e['cost_of_transport'], 3)} | "
                             f"{pm(e['min_stability_margin_deg'])} (worst {e['min_stability_margin_deg']['min']:.1f}) | {pm(e['peak_winding_C'])} | {pm(e['rms_longitudinal_slip_percent'])} |")
        zones = [z['id'] for z in arena['zones'] if any(z['id'] in pol[n]['zones'] for n in names)]
        w('\nZones passed, runs out of n:\n'); w('| Policy | ' + ' | '.join(zones) + ' |\n|---|' + '---|' * len(zones))
        for n in names: w(f"| {LABEL[n]} | " + ' | '.join(f"{pol[n]['zones'][z]['passed']}/{pol[n]['zones'][z]['runs']}" if z in pol[n]['zones'] else '–' for z in zones) + ' |')
        w('\nMean time per zone [s] (passed and failed attempts together):\n'); w('| Policy | ' + ' | '.join(zones) + ' |\n|---|' + '---|' * len(zones))
        for n in names: w(f"| {LABEL[n]} | " + ' | '.join(f"{pol[n]['zones'][z]['mean_time_s']:.1f}" if z in pol[n]['zones'] else '–' for z in zones) + ' |')
        w('\nPolicy definitions (`morph_sim/tour_core.py`): the two fixed policies keep one stance and use neither the corner-height actuators nor the torque boost. Reactive and proposed have the same')
        w('actuators and the same stance choice; they differ only in *when* the stance changes — reactive stops at the zone boundary and waits, proposed starts ahead using the predictive trigger.')
    else: w('Not measured yet: run `benchmarks/run_ablation_suite.py`.')

    w('\n## 5. Single-fixture measurements (one run each)\n')
    if fixtures:
        ramps = [r for r in fixtures['rows'] if r['kind'] == 'ramp']; trenches = [r for r in fixtures['rows'] if r['kind'] == 'trench']
        w('### Ramps\n'); w('| Run | Slope | Stance at start | Aids | Result | Wheelbase lowest during climb | Peak pitch | Peak winding |\n|---|---|---|---|---|---|---|---|')
        for r in ramps:
            aids = ', '.join(e for e in r['events'] if e not in ('expand', 'compact', 'normal')) or 'none'
            w(f"| `{r['run']}` | {r['slope_deg']:g}° | {r['wheelbase_start_mm']} mm | {aids} | {'**climbs**' if r['climbed'] else 'stalls'} (height gain {r['height_gain_m']:.2f} m) | {r['wheelbase_min_mm']} mm | {r['peak_pitch_deg']}° | {r['peak_winding_C']} °C |")
        w('\n### Trenches (100 / 130 / 155 mm)\n'); w('| Run | Stance | Body yaw | Aids | Trenches crossed | Peak pitch |\n|---|---|---|---|---|---|')
        for r in trenches:
            aids = ', '.join(dict.fromkeys(e for e in r['events'] if e not in ('expand', 'compact', 'normal', 'suspension_level'))) or 'none'
            w(f"| `{r['run']}` | {r['wheelbase_start_mm']} mm | {abs(r['yaw_deg']):.0f}° | {aids} | {', '.join(map(str, r['crossed_mm'])) or 'none'} | {r['peak_pitch_deg']}° |")
        if fixtures.get('holonomic'):
            w('\n### Three-degree-of-freedom command test (flat tarmac, Normal stance)\n'); w('| Command (vx, vy, ωz) | Steady body velocity | Heading change over 4 s | Final steering angles [deg] | Steering within 10° / 2° of final |\n|---|---|---|---|---|')
            for r in fixtures['holonomic']:
                w(f"| `{r['phase']}` {tuple(r['command_vx_vy_wz'])} | {tuple(r['steady_vx_vy_wz'])} | {r['heading_change_deg']:+.2f}° | {r['steering_final_deg']} | {r['steering_within_10deg_s']:.2f} s / {r['steering_within_2deg_s']:.2f} s |")
            w(f"\nThe steering setpoint slews at {steer['output_speed_limit_rad_s']:g} rad/s, so a 90° change takes {math.pi / 2 / steer['output_speed_limit_rad_s']:.2f} s at the setpoint; the simulated joint follows later, as the table shows.")
    else: w('Not reduced yet: run `benchmarks/summarise_fixtures.py`.')
    if onfly:
        w('\n### Shape change while driving at 0.3 m/s (continuous policy), against the same drive without a shape change\n')
        w('| Drive | Wheelbase range | Lateral deviation (reference run) | Heading difference | Path difference at the end | Slowest speed |\n|---|---|---|---|---|---|')
        for key, label in (('straight_morph', 'Straight'), ('straight_compact', 'Straight'), ('arc_morph', 'Arc, ωz = 0.2 rad/s'), ('crab_morph', 'Crab')):
            m = onfly.get(key)
            if m: w(f"| {label} | {m['wheelbase_min_max_mm'][0]}–{m['wheelbase_min_max_mm'][1]} mm | {m['lateral_deviation_max_mm'] if m['lateral_deviation_max_mm'] is not None else '–'} mm ({m['reference_lateral_deviation_max_mm'] if m['reference_lateral_deviation_max_mm'] is not None else '–'} mm) | {m['yaw_difference_max_deg']}° | {m['path_difference_end_mm']} mm | {m['speed_min_test_after_2s']} m/s |")
    if soil:
        w('\n### Soil lanes, 0.18 m/s\n'); w('| Run | Lane | Cost of transport | Soil resistance | Axle load front / rear | Soil slip front / rear |\n|---|---|---|---|---|---|')
        for run, lanes in soil.items():
            for lane, m in lanes.items():
                if isinstance(m, dict) and 'CoT' in m: w(f"| `{run}` | {lane} | {m['CoT']} | {m['soil_resistance_N']} N | {m['axle_load_front_rear_N'][0]} / {m['axle_load_front_rear_N'][1]} N | {m['soil_slip_front_rear'][0]} / {m['soil_slip_front_rear'][1]} |")

    w('\n## 6. Video\n')
    if video: w(f"`{video['file']}`: {video['width']}×{video['height']}, {video['fps']} fps, {video['duration_s']:.1f} s, {video['size_MB']} MB, {video['encoder']} at {video['bitrate_kbit_s']} kbit/s. Playback {video['playback_speed']:g}× simulation time; "
                 f"{video['frames']} frames of which {video['repeated_frames']} repeat the previous camera image. Policy `{video.get('policy')}`, {video.get('zones_passed')}/{video.get('zones_total')} zones passed in that run (`{video.get('run')}`).")
    else: w('Not recorded yet: run `video_pipeline/record_conference_video.py`.')

    w('\n## 7. What the data does and does not support\n')
    w('Supported by a measurement above (simulation, assumed parameters):\n')
    w('- The wheelbase decides which obstacles are passable: the per-zone table in section 4 and the ramp and trench tables in section 5.')
    w('- A shape change can run while driving straight or on an arc with sub-millimetre sideways deviation (section 5).')
    w('- A 380 mm passage is passed by Compact, yawed 90°, crabbing with the drive units turned inward.')
    w('\nNot supported, or contradicted, by the measurements — do not claim:\n')
    w('- Head-on trench crossing by ±15 mm suspension pitch: it crosses the 100 mm trench only. Oblique crossing is what works.')
    w('- Ramps of 18° and steeper: 20° and 22° need more force than the drive has even with the boost (' + f"{mass * dc.G * math.sin(math.radians(20)) + 2.2:.0f} N and {mass * dc.G * math.sin(math.radians(22)) + 2.2:.0f} N against {boost:.0f} N).")
    w('- "Sub-5 mm drift" without qualification: it holds sideways, not along the track.')
    w('- 90° steering alignment in under 0.49 s: that is the setpoint time; the joint needs about twice as long.')
    w('- Thermal throttling of the boost: no run came near the temperature where it starts.')
    w('- Any statement about a real robot. Soil constants, motor constants, masses and friction values are assumed.')
    (WS / 'reports/paper_ready_summary.md').write_text('\n'.join(out) + '\n'); print('wrote reports/paper_ready_summary.md', len(out), 'lines')


if __name__ == '__main__':
    main()
